17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
100	     *  separated by '@', none of which contain whitespace or a second '@'. */
101	    private static final java.util.regex.Pattern EMAIL_PATTERN =
102	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
103	
104	    /**
105	     * Normalize the optional email: absent stays absent; when present it must be syntactically
106	     * valid and is lower-cased. Returns {@code false} if present but invalid.
107	     */
108	    private boolean normalizeEmail(Owner owner) {
109	        String email = owner.getEmail();
110	        if (email == null || email.isEmpty()) {
111	            owner.setEmail(null);
112	            return true;
113	        }
114	        if (!EMAIL_PATTERN.matcher(email).matches()) {
115	            return false;
116	        }
117	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
118	        return true;
119	    }
120	
121	    /**
122	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
123	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
124	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
125	     *
126	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
127	     *         a valid E.164 number.
128	     */
129	    private static String toE164(String raw) {
130	        if (raw == null) {
131	            return null;
132	        }
133	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
134	        String digits;
135	        if (cleaned.startsWith("+")) {
136	            digits = cleaned.substring(1);
137	        } else {
138	            if (cleaned.startsWith("0")) {
139	                cleaned = cleaned.substring(1);
140	            }
141	            digits = "61" + cleaned;
142	        }
143	        if (!digits.matches("\\d{8,15}")) {
144	            return null;
145	        }
146	        return "+" + digits;
147	    }
148	
149	    /**
150	     * Build the customer code {@code <CITY3>-<LAST3>-<NNNN>}: CITY3 is the upper-cased first three
151	     * letters of the city, LAST3 the upper-cased first three letters of the last name and NNNN a
152	     * per-city 4-digit zero-padded sequence equal to one more than the owners already in that city
153	     * (e.g. {@code SYD-SMI-0007}).
154	     */
155	    private String nextCustomerCode(String city, String lastName) {
156	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(java.util.Locale.ROOT);
157	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(java.util.Locale.ROOT);
158	        int sequence = 1;
159	        for (Owner existing : this.clinicService.findAllOwners()) {
160	            if (city.equalsIgnoreCase(existing.getCity())) {
161	                sequence++;
162	            }
163	        }
164	        return String.format("%s-%s-%04d", city3, last3, sequence);
165	    }
166	
167	    /** Common street-type abbreviations expanded during address normalization. */
168	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
169	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
170	
171	    /**
172	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
173	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
174	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
175	     */
176	    private static String normalizeAddress(String value) {
177	        if (value == null) {
178	            return "";
179	        }
180	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
181	        if (collapsed.isEmpty()) {
182	            return "";
183	        }
184	        String[] tokens = collapsed.split(" ");
185	        StringBuilder sb = new StringBuilder(collapsed.length());
186	        for (int i = 0; i < tokens.length; i++) {
187	            if (i > 0) {
188	                sb.append(' ');
189	            }
190	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
191	        }
192	        return sb.toString();
193	    }
194	
195	    /**
196	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
197	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
198	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
199	     */
200	    private static String normalizeForHousehold(String value) {
201	        if (value == null) {
202	            return "";
203	        }
204	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
205	    }
206	
207	    /**
208	     * Return the owners that already share this owner's household, i.e. have the same last name and
209	     * address compared case-insensitively with collapsed whitespace.
210	     */
211	    private List<Owner> householdMembers(Owner owner) {
212	        String lastName = normalizeForHousehold(owner.getLastName());
213	        String address = normalizeForHousehold(owner.getAddress());
214	        List<Owner> members = new java.util.ArrayList<>();
215	        for (Owner existing : this.clinicService.findAllOwners()) {
216	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
217	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
218	                members.add(existing);
219	            }
220	        }
221	        return members;
222	    }
223	
224	    /**
225	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
226	     * last name and address compared case-insensitively with collapsed whitespace.
227	     */
228	    private boolean sharesHouseholdWithExisting(Owner owner) {
229	        return !householdMembers(owner).isEmpty();
230	    }
231	
232	    /**
233	     * Count the existing owners that share this owner's first name and last name, compared
234	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
235	     */
236	    private int namesakeCount(Owner owner) {
237	        String firstName = owner.getFirstName();
238	        String lastName = owner.getLastName();
239	        int count = 0;
240	        for (Owner existing : this.clinicService.findAllOwners()) {
241	            if (firstName != null && lastName != null
242	                && firstName.equalsIgnoreCase(existing.getFirstName())
243	                && lastName.equalsIgnoreCase(existing.getLastName())) {
244	                count++;
245	            }
246	        }
247	        return count;
248	    }
249	
250	    /**
251	     * A stable, shared household identifier derived from the normalized last name and address, so every
252	     * owner in the same household deterministically resolves to the same value.
253	     */
254	    private static String householdIdFor(Owner owner) {
255	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
256	        try {
257	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
258	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
259	            StringBuilder sb = new StringBuilder(24);
260	            for (int i = 0; i < 12; i++) {
261	                sb.append(String.format("%02X", digest[i]));
262	            }
263	            return sb.toString();
264	        }
265	        catch (java.security.NoSuchAlgorithmException e) {
266	            throw new IllegalStateException(e);
267	        }
268	    }
269	
270	    /** Maximum number of owners permitted in a single city. */
271	    private static final int CITY_CAPACITY = 50;
272	
273	    /**
274	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
275	     * Used to enforce the per-city capacity on create (before this owner is saved).
276	     */
277	    private int cityOwnerCount(Owner owner) {
278	        String city = owner.getCity();
279	        int count = 0;
280	        for (Owner existing : this.clinicService.findAllOwners()) {
281	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
282	                count++;
283	            }
284	        }
285	        return count;
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
291	        HttpHeaders headers = new HttpHeaders();
292	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
293	        String telephone = toE164(owner.getTelephone());
294	        if (telephone == null) {
295	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
296	        }
297	        if (!normalizeEmail(owner)) {
298	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
299	        }
300	        String address = normalizeAddress(owner.getAddress());
301	        if (address.isEmpty()) {
302	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
303	        }
304	        owner.setAddress(address);
305	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
306	            return new ResponseEntity<>(HttpStatus.CONFLICT);
307	        }
308	        for (Owner existing : this.clinicService.findAllOwners()) {
309	            String existingTelephone = toE164(existing.getTelephone());
310	            if (telephone.equals(existingTelephone)) {
311	                return new ResponseEntity<>(HttpStatus.CONFLICT);
312	            }
313	        }
314	        List<Owner> householdMembers = householdMembers(owner);
315	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
316	        if (!sharesHousehold && !householdMembers.isEmpty()) {
317	            return new ResponseEntity<>(HttpStatus.CONFLICT);
318	        }
319	        if (sharesHousehold && !householdMembers.isEmpty()) {
320	            String householdId = householdMembers.stream()
321	                .map(Owner::getHouseholdId)
322	                .filter(id -> id != null && !id.isBlank())
323	                .findFirst()
324	                .orElseGet(() -> householdIdFor(owner));
325	            owner.setHouseholdId(householdId);
326	            for (Owner member : householdMembers) {
327	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
328	                    member.setHouseholdId(householdId);
329	                    this.clinicService.saveOwner(member);
330	                }
331	            }
332	        }
333	        owner.setNamesakeCount(namesakeCount(owner));
334	        owner.setTelephone(telephone);
335	        if (owner.getRegistrationDate() == null) {
336	            owner.setRegistrationDate(java.time.LocalDate.now());
337	        }
338	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
339	        this.clinicService.saveOwner(owner);
340	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
341	        headers.setLocation(UriComponentsBuilder.newInstance()
342	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
343	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
344	    }
345	
346	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
347	    @Override
348	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
349	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
350	        if (currentOwner == null) {
351	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
352	        }
353	        currentOwner.setAddress(ownerFieldsDto.getAddress());
354	        currentOwner.setCity(ownerFieldsDto.getCity());
355	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
356	        currentOwner.setLastName(ownerFieldsDto.getLastName());
357	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
358	        currentOwner.setEmail(ownerFieldsDto.getEmail());
359	        if (!normalizeEmail(currentOwner)) {
360	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
361	        }
362	        this.clinicService.saveOwner(currentOwner);
363	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
364	    }
365	
366	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
367	    @Transactional
368	    @Override
369	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
370	        Owner owner = this.clinicService.findOwnerById(ownerId);
371	        if (owner == null) {
372	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
373	        }
374	        this.clinicService.deleteOwner(owner);
375	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
376	    }
377	
378	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
379	    @Override
380	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
381	        Owner owner = this.clinicService.findOwnerById(ownerId);
382	        if (owner == null) {
383	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
384	        }
385	        HttpHeaders headers = new HttpHeaders();
386	        Pet pet = petMapper.toPet(petFieldsDto);
387	        owner.setId(ownerId);
388	        pet.setOwner(owner);
389	        pet.getType().setName(null);
390	        this.clinicService.savePet(pet);
391	        PetDto petDto = petMapper.toPetDto(pet);
392	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
393	            .buildAndExpand(pet.getId()).toUri());
394	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
395	    }
396	
397	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
398	    @Override
399	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
400	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
401	        if (currentOwner != null) {
402	            Pet currentPet = this.clinicService.findPetById(petId);
403	            if (currentPet != null) {
404	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
405	                currentPet.setName(petFieldsDto.getName());
406	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
407	                this.clinicService.savePet(currentPet);
408	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
409	            }
410	        }
411	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
412	    }
413	
414	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
415	    @Override
416	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
417	        HttpHeaders headers = new HttpHeaders();
418	        Visit visit = visitMapper.toVisit(visitFieldsDto);
419	        Pet pet = new Pet();
420	        pet.setId(petId);
421	        visit.setPet(pet);
422	        this.clinicService.saveVisit(visit);
423	        VisitDto visitDto = visitMapper.toVisitDto(visit);
424	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
425	            .buildAndExpand(visit.getId()).toUri());
426	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
427	    }
428	
429	
430	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
431	    @Override
432	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
433	        Owner owner = this.clinicService.findOwnerById(ownerId);
434	        if (owner != null) {
435	            Pet pet = owner.getPet(petId);
436	            if (pet != null) {
437	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
438	            }
439	        }
440	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
441	    }
442	}
